#include <vector>

class Solution {
public:
    long long minOperations(std::vector<int>& nums) {
        long long ans = 0;
        for (int i = 1; i < (int)nums.size(); ++i) {
            if (nums[i - 1] > nums[i]) {
                ans += nums[i - 1] - nums[i];
            }
        }
        return ans;
    }
};

class Solution {
    public long minOperations(int[] nums) {
        long ans = 0;
        for (int i = 1; i < nums.length; i++) {
            if (nums[i - 1] > nums[i]) {
                ans += nums[i - 1] - nums[i];
            }
        }
        return ans;
    }
}

